const API_BASE = '/api'

export const api = {
  // 客户端接口
  getPosts(page = 1, perPage = 10, tag = '') {
    const params = new URLSearchParams({ page, per_page: perPage })
    if (tag) params.append('tag', tag)
    return fetch(`${API_BASE}/posts?${params}`).then(r => r.json())
  },

  getPost(id) {
    return fetch(`${API_BASE}/post/${id}`).then(r => r.json())
  },

  likePost(id) {
    return fetch(`${API_BASE}/post/${id}/like`, { method: 'POST' }).then(r => r.json())
  },

  getCurrentBackground() {
    return fetch(`${API_BASE}/background/current`).then(r => r.json())
  },

  getCategories() {
    return fetch(`${API_BASE}/categories`).then(r => r.json())
  },

  getTags() {
    return fetch(`${API_BASE}/tags`).then(r => r.json())
  },

  getRandomQuote() {
    return fetch(`${API_BASE}/quotes/random`).then(r => r.json())
  },

  getSettings() {
    return fetch(`${API_BASE}/settings`).then(r => r.json())
  },

  getStats() {
    return fetch(`${API_BASE}/stats`).then(r => r.json())
  },

  getAdminStats(token) {
    return fetch(`${API_BASE}/admin/stats`, {
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(r => r.json())
  },

  // 认证
  login(username, password) {
    return fetch(`${API_BASE}/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    }).then(r => r.json())
  },

  // 管理端接口
  getAdminArticles(token, status = '') {
    const url = status ? `${API_BASE}/admin/articles?status=${status}` : `${API_BASE}/admin/articles`
    return fetch(url, {
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(r => r.json())
  },

  createPost(token, formData) {
    return fetch(`${API_BASE}/admin/post`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${token}` },
      body: formData
    }).then(r => r.json())
  },

  updatePost(token, id, formData) {
    return fetch(`${API_BASE}/admin/post/${id}`, {
      method: 'PUT',
      headers: { 'Authorization': `Bearer ${token}` },
      body: formData
    }).then(r => r.json())
  },

  deletePost(token, id) {
    return fetch(`${API_BASE}/admin/post/${id}`, {
      method: 'DELETE',
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(r => r.json())
  },

  updateBackground(token, formData) {
    return fetch(`${API_BASE}/admin/background`, {
      method: 'PUT',
      headers: { 'Authorization': `Bearer ${token}` },
      body: formData
    }).then(r => r.json())
  },

  getStats(token) {
    return fetch(`${API_BASE}/stats`, {
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(r => r.json())
  },

  getLogs(token, page = 1, perPage = 20, action = '', startTime = '', endTime = '') {
    const params = new URLSearchParams({ page, per_page: perPage })
    if (action) params.append('action', action)
    if (startTime) params.append('start_time', startTime)
    if (endTime) params.append('end_time', endTime)
    return fetch(`${API_BASE}/admin/logs?${params}`, {
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(r => r.json())
  },

  // 分类管理
  createCategory(token, name, slug) {
    return fetch(`${API_BASE}/admin/category`, {
      method: 'POST',
      headers: { 
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: `name=${encodeURIComponent(name)}&slug=${encodeURIComponent(slug || name)}`
    }).then(r => r.json())
  },

  updateCategory(token, id, name, slug) {
    return fetch(`${API_BASE}/admin/category/${id}`, {
      method: 'PUT',
      headers: { 
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: `name=${encodeURIComponent(name)}&slug=${encodeURIComponent(slug || name)}`
    }).then(r => r.json())
  },

  deleteCategory(token, id) {
    return fetch(`${API_BASE}/admin/category/${id}`, {
      method: 'DELETE',
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(r => r.json())
  },

  // 标签管理
  createTag(token, name, slug) {
    return fetch(`${API_BASE}/admin/tag`, {
      method: 'POST',
      headers: { 
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: `name=${encodeURIComponent(name)}&slug=${encodeURIComponent(slug || name)}`
    }).then(r => r.json())
