  createUser(token, username, password, roleIds = []) {
    return fetch(`${API_BASE}/admin/user`, {
      method: 'POST',
      headers: { 
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ username, password, role_ids: roleIds })
    }).then(r => r.json())
  },

  updateUserRoles(token, id, roleIds) {
    return fetch(`${API_BASE}/admin/user/${id}/roles`, {
      method: 'PUT',
      headers: { 
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ role_ids: roleIds })
    }).then(r => r.json())
  },

  // 角色管理
  getRoles(token) {
    return fetch(`${API_BASE}/admin/roles`, {
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(r => r.json())
  },

  getRole(token, id) {
    return fetch(`${API_BASE}/admin/role/${id}`, {
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(r => r.json())
  },

  createRole(token, name, key, description, permissionIds) {
    return fetch(`${API_BASE}/admin/role`, {
      method: 'POST',
      headers: { 
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ name, key, description, permission_ids: permissionIds })
    }).then(r => r.json())
  },

  updateRole(token, id, name, description, permissionIds) {
    return fetch(`${API_BASE}/admin/role/${id}`, {
      method: 'PUT',
      headers: { 
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ name, description, permission_ids: permissionIds })
    }).then(r => r.json())
  },

  deleteRole(token, id) {
    return fetch(`${API_BASE}/admin/role/${id}`, {
      method: 'DELETE',
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(r => r.json())
  },

  // 权限列表
  getPermissions(token) {
    return fetch(`${API_BASE}/admin/permissions`, {
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(r => r.json())
  }
}

import { test } from 'node:test';
import assert from 'node:assert';
import { api } from './api.js';

function mockFetch(response = {}) {
  const calls = [];
  global.fetch = async (url, options = {}) => {
    calls.push({ url, options });
    return {
      json: async () => response
    };
  };
  return calls;
}


test('uploadImage is defined as a function on the api object', () => {
  assert.strictEqual(typeof api.uploadImage, 'function');
});

