import { test } from 'node:test';
import assert from 'node:assert';
import { api } from './api.js';

function mockFetch(response = {}) {
  const calls = [];
  global.fetch = async (url, options = {}) => {
    calls.push({ url, options });
    return {
      json: async () => response
    };
  };
  return calls;
}


test('uploadImage sends POST request to /api/admin/upload-image with Bearer token', async () => {
  const calls = mockFetch({ success: true, url: '/uploads/test.png' });
  const formData = new FormData();

  await api.uploadImage('my-token', formData);

  assert.strictEqual(calls.length, 1);
  assert.strictEqual(calls[0].url, '/api/admin/upload-image');
  assert.strictEqual(calls[0].options.method, 'POST');
  assert.strictEqual(calls[0].options.headers.Authorization, 'Bearer my-token');
});


test('uploadImage passes formData as the request body', async () => {
  const calls = mockFetch({ success: true });
  const formData = new FormData();

  await api.uploadImage('token123', formData);

  assert.strictEqual(calls[0].options.body, formData);
});


test('uploadImage returns the parsed JSON response', async () => {
  const expectedResponse = { success: true, url: '/uploads/cover.jpg' };
  mockFetch(expectedResponse);

  const result = await api.uploadImage('token', new FormData());

  assert.deepStrictEqual(result, expectedResponse);
});


test('createPost still works correctly (existing functionality)', async () => {
  const calls = mockFetch({ id: 1, title: 'Test' });
  const formData = new FormData();

  await api.createPost('admin-token', formData);

  assert.strictEqual(calls.length, 1);
  assert.strictEqual(calls[0].url, '/api/admin/post');
  assert.strictEqual(calls[0].options.method, 'POST');
  assert.strictEqual(calls[0].options.headers.Authorization, 'Bearer admin-token');
  assert.strictEqual(calls[0].options.body, formData);
});
